#!/usr/bin/env python3
import hashlib, html, io, json, runpy, time, urllib.parse, urllib.request
from pathlib import Path
from PIL import Image
base=runpy.run_path(str(Path(__file__).with_name('publish_recipe_20260825_1000.py')),run_name='recipe_base')
TITLE='Biscoito Caseiro de Aveia sem Açúcar para Bebê: Receita Macia'; SLUG_KEY='biscoito-caseiro-aveia-sem-acucar-bebe'; CLUSTER='Cluster 3 — Café da manhã e lanches sem açúcar'; KEYWORD='biscoito caseiro de aveia sem açúcar para bebê'
MARKER=base['MARKER']; BLOG_ID=base['BLOG_ID']; COVER_DIR=base['COVER_DIR']; RAW_BASE=base['RAW_BASE']; LOG_PATH=base['LOG_PATH']; RESULT_PATH=base['RESULT_PATH']; W,H=1200,630

def generate_cover(path):
 p="Photorealistic horizontal food photograph of homemade soft oat cookies for a baby-friendly no-added-sugar recipe, several small rustic pale-golden oatmeal cookies with tender soft centers and visible oat flakes, arranged on a matte cream ceramic plate, a few rolled oats scattered naturally nearby, warm afternoon window light, light wood table, soft beige linen, realistic home food photography, close three-quarter view, natural imperfections, appetizing but simple. No sugar crystals, icing, frosting, honey, syrup, chocolate, baby, child, people, hands, text, logo, watermark, packaging, collage, illustration or cartoon."
 enc=urllib.parse.quote(p,safe=''); seed=int(hashlib.sha256(TITLE.encode()).hexdigest()[:12],16)%2147483647; last=None
 for a in range(8):
  try:
   u=f'https://image.pollinations.ai/prompt/{enc}?width={W}&height={H}&model=flux&nologo=true&safe=true&enhance=true&seed={seed+a*10007}'; req=urllib.request.Request(u,headers={'User-Agent':'Mozilla/5.0 (compatible; ReceitasParaPequenos/3.0)','Accept':'image/*'})
   with urllib.request.urlopen(req,timeout=240) as r: raw=r.read()
   if len(raw)<15000: raise RuntimeError('small image response')
   im=Image.open(io.BytesIO(raw)).convert('RGB'); tr=W/H; cr=im.width/im.height
   if cr>tr: nw=int(im.height*tr); x=(im.width-nw)//2; im=im.crop((x,0,x+nw,im.height))
   elif cr<tr: nh=int(im.width/tr); y=(im.height-nh)//2; im=im.crop((0,y,im.width,y+nh))
   im=im.resize((W,H),Image.Resampling.LANCZOS); path.parent.mkdir(parents=True,exist_ok=True); im.save(path,'JPEG',quality=92,optimize=True,progressive=True); return
  except Exception as e: last=e; time.sleep(min(10*(a+1),45))
 raise RuntimeError(f'cover generation failed: {last}')

def article(cover):
 schema={'@context':'https://schema.org','@type':'Recipe','name':TITLE,'image':[cover],'author':{'@type':'Organization','name':'Equipe Editorial do Receitas Para Pequenos'},'description':'Biscoito caseiro de aveia sem açúcar adicionado, assado apenas até firmar para manter uma textura macia.','recipeCategory':'Lanche','recipeCuisine':'Brasileira','keywords':KEYWORD+', lanche sem açúcar, receita com aveia','recipeYield':'1 pequena porção','recipeIngredient':['1 ovo','5 colheres (sopa) de aveia em flocos finos','2 colheres (sopa) de purê de maçã cozida sem açúcar','1 colher (sopa) de água, se necessário'],'recipeInstructions':[{'@type':'HowToStep','text':'Misture o ovo e o purê de maçã.'},{'@type':'HowToStep','text':'Junte a aveia e deixe hidratar brevemente.'},{'@type':'HowToStep','text':'Modele discos pequenos e asse somente até firmarem e cozinharem por completo, sem deixá-los duros.'}]}
 sj=json.dumps(schema,ensure_ascii=False).replace('</','<\\/'); alt=html.escape(TITLE,quote=True)
 return f"""{MARKER}<div class='separator' style='clear:both;margin:0 0 24px;text-align:center'><img alt='{alt}' data-original-height='630' data-original-width='1200' src='{cover}' style='border-radius:14px;height:auto;max-width:100%;width:1200px'/></div><p><strong>Por Equipe Editorial do Receitas Para Pequenos</strong></p><p>Este biscoito caseiro de aveia é uma opção simples para variar o lanche sem adicionar açúcar. A proposta desta receita não é fazer um biscoito seco e crocante: ele é assado apenas até cozinhar e firmar, mantendo o centro macio.</p><p><strong>Atenção:</strong> adapte tamanho, formato e textura às habilidades da criança e ofereça sempre com ela sentada e supervisionada. Alergias, dificuldades de mastigação/deglutição e necessidades especiais exigem orientação profissional individualizada.</p><h2>Ingredientes</h2><ul><li>1 ovo</li><li>5 colheres (sopa) de aveia em flocos finos</li><li>2 colheres (sopa) de purê de maçã cozida, sem açúcar</li><li>1 colher (sopa) de água, apenas se a mistura ficar seca demais</li></ul><h2>Modo de preparo</h2><ol><li>Preaqueça o forno a 180 °C e forre uma assadeira.</li><li>Misture o ovo com o purê de maçã até ficar uniforme.</li><li>Acrescente a aveia e aguarde alguns minutos para que ela absorva parte da umidade.</li><li>Se a massa estiver quebradiça, acrescente a água aos poucos. Ela deve ficar úmida e moldável.</li><li>Faça pequenos discos achatados na assadeira.</li><li>Asse apenas até os biscoitos firmarem e o ovo estar completamente cozido. Retire antes que fiquem secos ou muito duros e deixe amornar.</li></ol><h2>Como deve ficar a textura</h2><p>O resultado esperado é um biscoito macio, que cede à pressão e não apresenta bordas rígidas. Como as habilidades variam entre crianças, confira a textura antes de oferecer e adapte o formato quando necessário.</p><h2>Como servir e adaptar</h2><p>Sirva sem coberturas, açúcar, mel ou caldas. O tamanho e o formato devem ser escolhidos conforme as habilidades da criança. Se o biscoito esfriar e ficar mais firme do que o desejado, não o ofereça nessa textura.</p><h2>Por que não adicionamos açúcar?</h2><p>O Ministério da Saúde orienta não oferecer açúcar nem preparações com açúcar para crianças menores de 2 anos. Nesta receita, o purê de maçã entra principalmente para dar umidade e sabor à massa, sem necessidade de adoçar.</p><h2>Substituições culinárias</h2><p>A aveia em flocos finos pode absorver quantidades diferentes de líquido, por isso a água é opcional e deve ser acrescentada aos poucos. Substituições relacionadas a alergia ao ovo ou a outros ingredientes devem ser discutidas com profissional habilitado.</p><h2>Perguntas frequentes</h2><h3>O biscoito precisa ficar crocante?</h3><p>Não. Nesta receita, o objetivo é justamente manter uma textura macia. Um biscoito muito seco ou duro não corresponde ao resultado proposto.</p><h3>Posso colocar mel?</h3><p>Não é necessário. A receita foi pensada sem açúcar adicionado e sem mel.</p><h3>Posso usar aveia mais grossa?</h3><p>Para esta versão, os flocos finos facilitam a formação de uma massa mais uniforme e macia.</p><h2>Receitas relacionadas</h2><ul><li><a href='https://www.receitasparapequenos.site/2026/08/pao-de-cenoura-caseiro-para-bebe.html'>Pão de Cenoura Caseiro para Bebê</a></li><li><a href='https://www.receitasparapequenos.site/2026/08/muffin-de-maca-e-aveia-sem-acucar-para.html'>Muffin de Maçã e Aveia sem Açúcar para Bebê</a></li><li><a href='https://www.receitasparapequenos.site/2026/08/panqueca-de-pera-e-aveia-sem-acucar.html'>Panqueca de Pera e Aveia sem Açúcar para Bebê</a></li></ul><h2>Referências oficiais</h2><ul><li><a href='https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/s/saude-da-crianca/primeira-infancia/alimentacao-saudavel' rel='nofollow'>Ministério da Saúde — Alimentação saudável na primeira infância</a></li><li><a href='https://www.gov.br/saude/pt-br/composicao/saps/promocao-da-saude/guias-alimentares/publicacoes/guia_da_crianca_2019.pdf/view' rel='nofollow'>Ministério da Saúde — Guia Alimentar para Crianças Brasileiras Menores de 2 Anos</a></li></ul><script type='application/ld+json'>{sj}</script>"""

def main():
 tok=base['token'](); posts=base['list_posts'](tok)
 for p in posts:
  t=(p.get('title') or '').casefold()
  if t==TITLE.casefold() or ('biscoito' in t and 'aveia' in t and 'açúcar' in t):
   RESULT_PATH.write_text(f'outcome=skipped_duplicate\ntitle={p.get("title","")}\nurl={p.get("url","")}\n',encoding='utf-8'); base['git_commit_push']([RESULT_PATH],'Record duplicate prevention for oat cookie'); return
 suffix=hashlib.sha1(TITLE.encode()).hexdigest()[:10]; cp=COVER_DIR/f'{SLUG_KEY}-{suffix}.jpg'; cu=f'{RAW_BASE}/{cp.name}'
 if not cp.exists(): generate_cover(cp); base['git_commit_push']([cp],'Add unique AI food photo for oat cookie'); time.sleep(8)
 content=article(cu)
 if MARKER not in content or cu not in content: raise RuntimeError('cover verification failed before publish')
 created=base['api'](tok,'POST',f'/blogs/{BLOG_ID}/posts',{'isDraft':'false','fetchBody':'true'},{'kind':'blogger#post','blog':{'id':BLOG_ID},'title':TITLE,'content':content,'labels':['Alimentação complementar','Café da manhã','Lanche','Aveia','Sem açúcar']}); pid=str(created.get('id','')); url=created.get('url','')
 if not pid: raise RuntimeError('Blogger did not return post id')
 vc=(base['api'](tok,'GET',f'/blogs/{BLOG_ID}/posts/{pid}',{'view':'ADMIN'}).get('content') or '')
 if MARKER not in vc or cu not in vc: raise RuntimeError('live Blogger post failed cover verification')
 log=base['load_log'](); log.append({'published_at':created.get('published'),'title':TITLE,'url':url,'post_id':pid,'cluster':CLUSTER,'keyword':KEYWORD,'cover_url':cu,'marker':MARKER}); LOG_PATH.write_text(json.dumps(log,ensure_ascii=False,indent=2)+'\n',encoding='utf-8'); RESULT_PATH.write_text('outcome=success\n'+f'title={TITLE}\nurl={url}\npost_id={pid}\ncluster={CLUSTER}\ncover_url={cu}\nmarker_verified=true\n',encoding='utf-8'); base['git_commit_push']([LOG_PATH,RESULT_PATH],'Record published oat cookie recipe')
if __name__=='__main__': main()
